import { BlockManager } from "../BlockOperate/BlockManager";
import { MyEventListener } from "../Utilities/Event/MyEventListener";
import { LoopManager } from "../Utilities/Loop/LoopManager";
import { Monoiamond } from "../BlockOperate/Monoiamond";
import * as Setting from "../Config/GameConfig";
import { SeededRandom } from "../Utilities/Random/SeededRandom";
import { SimulationClock } from "../Utilities/Loop/SimulationClock";
import { SimulationLoop } from "../Utilities/Loop/SimulationLoop";

/**
 * じゃまモンドに関連する処理を行う
 */
export class NuisanceMondManager extends MyEventListener {
    //実際にnuisanceBlockを表示するblockManager
    private blockManager: BlockManager;
    //現在盤面上にあるnuisanceBlockを持つ配列
    private nuisanceMonds: Monoiamond[] = [];
    //前回のdamageによるpenalty
    //どのブロックも破壊しないまま地面に着いたnuisanceBlockの数
    private penalty: number = 0;
    //damage処理中ならtrue
    private damaging: boolean = false;
    //progressを繰り返し実行する用のinterval
    private readonly loop: LoopManager | SimulationLoop;
    //damage用に生成するnuisanceBlockの個数
    private task = 0;
    //一回のdamage中のnuisanceBlockの生成の進行度合い
    private taskCount = 0;
    //nuisanceBlockを三回に一回にする用のcount
    private progressCount = 0;
    private random: SeededRandom;
    private playbackSpeed = 1;

    /**
     * @param startDamage ダメージ処理開始
     * @param destroyMond モンド破壊
     * @param damageBoard 盤面へのダメージ
     * @param finishDamage ダメージ処理終了
     * @param collapseDamage 盤面が空になった後の残りをまとめて時間ペナルティに変換
     */
    constructor(blockManager: BlockManager, seed: number, clock?: SimulationClock) {
        super();
        this.loop = clock ? new SimulationLoop(clock) : new LoopManager();
        this.blockManager = blockManager;
        this.random = new SeededRandom(seed);
        this.loop.addHandler("loop", () => this.damageProcess());
    }

    dispose(): void {
        this.stop();
        this.loop.removeAllEvent();
        this.removeAllEvent();
    }

    //damage処理中でないときは前回のdamageによるpenaltyを返す
    //damage処理中のときは-1を返す
    get g$penalty(): number {
        if (this.damaging) return -1;
        return this.penalty;
    }

    //damageProgressを呼び出す頻度を取得する
    private get g$progressFrequency(): number {
        const frequency = Math.floor(Setting.damageTime / (Setting.damageGrace * (this.task - 1) + Setting.playHeight));
        if (frequency < 5) return 5;
        else return frequency;
    }

    //指定した座標でNuisanceBlockを生成する
    private createNuisanceBlock(x: number, y: number) {
        const nuisanceMond = new Monoiamond(x, y, "g", false);
        if (this.blockManager.canDisplayMonoiamond(nuisanceMond)) {
            this.blockManager.displayMonoiamond(nuisanceMond);
            this.nuisanceMonds.push(nuisanceMond);
        } else {
            const targetX = !this.blockManager.getBlockProperty(x, y)[1] ? x : 0 < x ? x - 1 : x < Setting.playWidth - 1 ? x + 1 : x;
            const existed = this.blockManager.getBlockProperty(targetX, y)[2];
            this.blockManager.remove(targetX, y);
            // 出現位置での衝突も、落下途中と同じ破壊として知らせる。
            if (existed) this.executeEvent("destroyMond");
        }
    }

    //taskの分だけNuisanceBlockによるdamage処理を行う
    damage(task: number) {
        //すでにdamage処理中のとき、taskを増やす
        if (this.damaging && task > 0) {
            this.task += task;
            this.loop.reset();
            this.loop.s$loopFrequency = this.g$progressFrequency;
            this.loop.start(this.playbackSpeed);
            return;
        }

        this.damaging = true;
        this.penalty = 0;
        this.task = task;
        this.progressCount = 0;
        this.loop.reset();
        this.loop.s$loopFrequency = this.g$progressFrequency;
        this.loop.s$speedMagnification = this.playbackSpeed;
        this.executeEvent("startDamage");
    }

    //NuisanceBlockを進行させて、すでにあるブロックとぶつかった場合は対消滅する
    private progress() {
        let damageBoard = false;
        for (const nuisanceMond of this.nuisanceMonds) {
            damageBoard = false;

            const visible = (dx: number, dy: number) => {
                return this.blockManager.getBlockProperty(nuisanceMond.g$x + dx, nuisanceMond.g$y + dy)[2];
            };

            const direction = (dx: number, dy: number) => {
                return this.blockManager.getBlockProperty(nuisanceMond.g$x + dx, nuisanceMond.g$y + dy)[1];
            };
            const remove = (dx: number, dy: number) => {
                if (dx != 0 || dy != 0) {
                    this.blockManager.remove(nuisanceMond.g$x + dx, nuisanceMond.g$y + dy);
                }
                this.blockManager.removeMonoiamond(nuisanceMond);
            };

            const isGrounded = () => {
                return nuisanceMond.g$y == Setting.playHeight - 1;
            };

            //左端でも右端でもないとき
            if (0 < nuisanceMond.g$x && nuisanceMond.g$x < Setting.playWidth - 1) {
                //左隣が存在するとき
                if (visible(-1, 0)) {
                    remove(-1, 0);
                    //右隣が存在するとき
                } else if (visible(1, 0)) {
                    remove(1, 0);
                    //一番下に着いたとき
                    //このときは対消滅するブロックがないため、代わりにpenaltyを受ける
                } else if (isGrounded()) {
                    damageBoard = true;
                    remove(0, 0);
                    //真下が下向きで存在するとき
                } else if (visible(0, 1) && !direction(0, 1)) {
                    remove(0, 1);
                    //左下が下向きで存在するとき
                } else if (visible(-1, 1) && !direction(-1, 1)) {
                    remove(-1, 1);
                    //右下が下向きで存在するとき
                } else if (visible(1, 1) && !direction(1, 1)) {
                    remove(1, 1);
                    //真下が上向きで存在するとき
                } else if (visible(0, 1)) {
                    remove(0, 1);
                }
                //左端ではないとき
            } else if (0 < nuisanceMond.g$x) {
                //左隣が存在するとき
                if (visible(-1, 0)) {
                    remove(-1, 0);
                    //一番下に着いたとき
                    //このときは対消滅するブロックがないため、代わりにpenaltyを受ける
                } else if (isGrounded()) {
                    damageBoard = true;
                    remove(0, 0);
                    //真下が下向きで存在するとき
                } else if (visible(0, 1) && !direction(0, 1)) {
                    remove(0, 1);
                    //左下が下向きで存在するとき
                } else if (visible(-1, 1) && !direction(-1, 1)) {
                    remove(-1, 1);
                    //真下が上向きで存在するとき
                } else if (visible(0, 1)) {
                    remove(0, 1);
                }
                //右端ではないとき
            } else if (nuisanceMond.g$x < Setting.playWidth - 1) {
                //右隣が存在するとき
                if (visible(1, 0)) {
                    remove(1, 0);
                    //一番下に着いたとき
                    //このときは対消滅するブロックがないため、代わりにpenaltyを受ける
                } else if (isGrounded()) {
                    damageBoard = true;
                    remove(0, 0);
                    //真下が下向きで存在するとき
                } else if (visible(0, 1) && !direction(0, 1)) {
                    remove(0, 1);
                    //右下が下向きで存在するとき
                } else if (visible(1, 1) && !direction(1, 1)) {
                    remove(1, 1);
                    //真下が上向きで存在するとき
                } else if (visible(0, 1)) {
                    remove(0, 1);
                }
                //右端かつ左端のとき
            } else {
                //一番下に着いたとき
                if (isGrounded()) {
                    damageBoard = true;
                    remove(0, 0);
                    //真下が存在するとき
                } else if (visible(0, 1)) {
                    remove(0, 1);
                }
            }

            //上記の条件に一つも引っかからなかったとき
            if (nuisanceMond.g$visible) {
                this.blockManager.removeMonoiamond(nuisanceMond);
                nuisanceMond.s$y = nuisanceMond.g$y + 1;
                this.blockManager.displayMonoiamond(nuisanceMond);
            } else {
                if (damageBoard) {
                    this.executeEvent("damageBoard");
                    this.penalty++;
                } else {
                    this.executeEvent("destroyMond");
                }
            }
        }

        //対消滅したnuisanceBlockをリストから削除する
        this.nuisanceMonds = this.nuisanceMonds.filter((nuisanceMond) => nuisanceMond.g$visible);
        this.executeEvent("progress");
    }

    //progressFrequencyの頻度でNuisanceBlockを進行させつつ、三回に一回の割合で、taskの分だけNuisanceBlockを生成する
    private damageProcess() {
        if (this.finishEmptyBoardDamage()) return;
        if (this.progressCount == 0) {
            //指定されたtaskの量の生成が完了していないとき
            if (this.taskCount < this.task) {
                this.progress();
                const x = this.random.nextInt(Setting.playWidth);
                this.createNuisanceBlock(x, 0);
                this.progressCount++;
                this.taskCount++;
                //すでにtaskの量の生成を完了していて、盤面に残っているnuisanceBlockが存在しないとき
            } else if (this.nuisanceMonds.length == 0) {
                this.finishDamage();
                //すでにtaskの量の生成を完了しているが盤面にnuisanceBlockが残っているとき
            } else {
                this.progress();
            }
        } else {
            //盤面に残っているnuisanceBlockが存在しないとき
            if (this.nuisanceMonds.length == 0) {
                this.progressCount = 0;
                //盤面にnuisanceBlockが残っているとき
            } else {
                this.progress();
                this.progressCount++;
            }

            if (this.progressCount == Setting.damageGrace) {
                this.progressCount = 0;
            }
        }
    }

    private finishEmptyBoardDamage(): boolean {
        if (this.loop.g$elapsedTime <= Setting.emptyBoardDamageCutTime || !this.blockManager.isEmpty(this.nuisanceMonds)) return false;
        const remaining = this.task - this.taskCount + this.nuisanceMonds.filter((mond) => mond.g$visible).length;
        if (remaining <= 0) return false;
        this.nuisanceMonds.forEach((mond) => this.blockManager.removeMonoiamond(mond));
        this.nuisanceMonds = [];
        this.penalty += remaining;
        this.executeEvent("collapseDamage", remaining);
        this.finishDamage();
        return true;
    }

    //damage処理を終了させる
    private finishDamage() {
        this.loop.reset();
        this.task = 0;
        this.progressCount = 0;
        this.taskCount = 0;
        this.damaging = false;
        this.executeEvent("finishDamage");
    }

    //damage処理を中止する
    cancelDamage(): void {
        this.loop.reset();
        for (const nuisanceMond of this.nuisanceMonds) {
            this.blockManager.removeMonoiamond(nuisanceMond);
        }
        this.task = 0;
        this.progressCount = 0;
        this.taskCount = 0;
        this.damaging = false;
    }

    /**
     * damage処理を一時中断する
     */
    stop(): void {
        if (!this.damaging) {
            return;
        }
        this.loop.stop();
    }

    /**
     * 一時中断していたdamage処理を再開する
     */
    start(): void {
        if (!this.damaging) {
            return;
        }
        this.loop.start(this.playbackSpeed);
    }

    setPlaybackSpeed(speed: number): void {
        this.playbackSpeed = speed;
        this.loop.s$speedMagnification = speed;
    }
}
