import { htmlQSAddEvent } from "../Utilities/Element/Query";
import { sceneManager } from "../Utilities/Scene/SceneManager";
import { defaultMaxGameTime } from "../Config/GameConfig";
import { getModeHelpPageId } from "../UI/HelpPages";
import { defaultTargetScore, minTargetScore, maxTargetScore } from "../Game/ScoreChallengeRules";
import { formatScoreTarget } from "../Utilities/Text/JapaneseText";

export type PlaySetting = Readonly<EditablePlaySetting>;

type EditablePlaySetting = {
    playerNumber: number;
    mode: number;
    maxGameTime: number;
    handy: number[];
    targetLines: number;
    targetScore: number;
};

/**
 * ゲームが始まる直前の人数とかルールとかを決める
 */
export class PlaySettingSetter {
    private static readonly playSetting: EditablePlaySetting = {
        playerNumber: 1,
        mode: 1,
        maxGameTime: defaultMaxGameTime,
        handy: [1],
        targetLines: 15,
        targetScore: defaultTargetScore,
    };

    /**
     * @returns 変更不可なplaySetting
     */
    static getPlaySetting(): PlaySetting {
        return Object.freeze(structuredClone(this.playSetting));
    }

    static setEvents() {
        // モードを決める
        htmlQSAddEvent(".button[data-mode]", "click", (element) => {
            // 一人プレイの時は聞かれないので1にしておく
            this.playSetting.playerNumber = 1;
            this.playSetting.mode = Number(element.dataset.mode);
        });

        // 人数を決める
        htmlQSAddEvent(".button[data-player]", "click", (element) => {
            this.playSetting.playerNumber = Number(element.dataset.player);
            this.playSetting.handy = Array.from({ length: this.playSetting.playerNumber }, (_, index) => this.playSetting.handy[index] ?? 1);
        });

        htmlQSAddEvent("#playPrepareSettingButton", "click", () => {
            sceneManager.g$currentPageManager?.openPage(this.playSetting.mode === 1 ? "survivalPlaySetting" : this.playSetting.mode === 2 ? "linePlaySetting" : "scorePlaySetting");
        });

        document.querySelectorAll<HTMLElement>("#survivalPlaySetting [data-max-time]").forEach((button) => {
            button.addEventListener("click", () => {
                this.playSetting.maxGameTime = button.dataset.maxTime === "Infinity" ? Infinity : Number(button.dataset.maxTime);
                this.render();
            });
        });

        document.querySelectorAll<HTMLElement>("#survivalPlaySetting [data-handy-player][data-handy-delta]").forEach((button) => {
            button.addEventListener("click", () => {
                const playerIndex = Number(button.dataset.handyPlayer);
                const delta = Number(button.dataset.handyDelta);
                const current = this.playSetting.handy[playerIndex] ?? 1;
                this.playSetting.handy[playerIndex] = Math.round(Math.max(0.1, Math.min(10, current + delta)) * 10) / 10;
                this.render();
            });
        });

        document.querySelectorAll<HTMLElement>("#linePlaySetting [data-target-lines-delta]").forEach((button) => {
            button.addEventListener("click", () => {
                this.playSetting.targetLines = Math.max(1, Math.min(30, this.playSetting.targetLines + Number(button.dataset.targetLinesDelta)));
                this.render();
            });
        });

        document.querySelectorAll<HTMLElement>("#scorePlaySetting [data-target-score-delta]").forEach((button) => {
            button.addEventListener("click", () => {
                this.playSetting.targetScore = Math.max(minTargetScore, Math.min(maxTargetScore, this.playSetting.targetScore + Number(button.dataset.targetScoreDelta)));
                this.render();
            });
        });

        sceneManager.g$currentPageManager?.addHandler(["changePage-playPrepare", "changePage-survivalPlaySetting", "changePage-linePlaySetting", "changePage-scorePlaySetting"], () => this.render());
        this.render();
    }

    private static render(): void {
        const modeHelpButton = document.getElementById("playPrepareModeHelpButton");
        if (modeHelpButton) modeHelpButton.dataset.page = getModeHelpPageId(this.playSetting.mode, this.playSetting.playerNumber);
        // 両段のボタンを同じ列に配置して見た目と方向入力の座標を一致させる
        const prepare = document.getElementById("playPrepare");
        if (prepare) prepare.dataset.mode = String(this.playSetting.mode);
        const trickListButton = document.getElementById("playPrepareTrickListButton");
        if (trickListButton) {
            trickListButton.hidden = this.playSetting.mode === 2;
            trickListButton.dataset.xy = "[0,2]";
        }
        const back = prepare?.querySelector<HTMLElement>(".back");
        if (back) back.dataset.xy = this.playSetting.mode !== 2 ? "[-1,3]" : "[-1,2]";
        const controls = document.getElementById("playPrepareControllerButton");
        if (controls) controls.textContent = this.playSetting.playerNumber === 1 ? "操作設定" : "プレイヤー別配置";
        const summary = document.getElementById("playPrepareSummary");
        if (summary) {
            const { mode, playerNumber, maxGameTime, targetLines, targetScore, handy } = this.playSetting;
            summary.replaceChildren();
            const rule = document.createElement("div");
            rule.className = "prepareRule";
            rule.textContent = `${mode === 1 ? "サバイバル" : mode === 2 ? "十五列揃え" : "五万点チャレンジ"} ／ ${playerNumber === 1 ? "ひとりで" : `${playerNumber}人で`} ／ ${mode === 1 ? `最大持ち時間 ${maxGameTime === Infinity ? "" : maxGameTime}` : mode === 2 ? `${targetLines}列` : `目標スコア ${formatScoreTarget(targetScore)}`}`;
            if (mode === 1 && maxGameTime === Infinity) {
                const symbol = document.createElement("span");
                symbol.className = "infinitySymbol";
                symbol.textContent = "∞";
                rule.appendChild(symbol);
            }
            summary.appendChild(rule);
            if (mode === 1) {
                const handicaps = document.createElement("div");
                handicaps.className = "prepareHandicaps";
                handicaps.textContent = "ハンデ　" + Array.from({ length: playerNumber }, (_, i) => `P${i + 1} ×${(handy[i] ?? 1).toFixed(1)}`).join("　");
                summary.appendChild(handicaps);
            }
        }

        document.querySelectorAll<HTMLElement>("#survivalPlaySetting [data-max-time]").forEach((button) => {
            const value = button.dataset.maxTime === "Infinity" ? Infinity : Number(button.dataset.maxTime);
            button.classList.toggle("selectedValue", value === this.playSetting.maxGameTime);
        });

        document.querySelectorAll<HTMLElement>("#survivalPlaySetting [data-handy-row]").forEach((row) => {
            const playerIndex = Number(row.dataset.handyRow);
            row.style.display = playerIndex < this.playSetting.playerNumber ? "flex" : "none";
            const value = row.querySelector<HTMLElement>(".handyValue");
            if (value) value.textContent = `×${(this.playSetting.handy[playerIndex] ?? 1).toFixed(1)}`;
        });

        const targetScore = document.getElementById("targetScoreValue");
        if (targetScore) targetScore.textContent = formatScoreTarget(this.playSetting.targetScore);
        const targetLines = document.getElementById("targetLinesValue");
        if (targetLines) targetLines.textContent = `${this.playSetting.targetLines}列`;
    }
}
